// 2025-1-19 21:25:12   2025-1-19 21:54:31
// 彭罗斯镶嵌第四法：L 系统  2156
//
//    L-system
// 
// https://openprocessing.org/sketch/1150163
// https://processing.org/examples/penrosetile.html
//
//    axiom = "[X]++[X]++[X]++[X]++[X]";
//    ruleW = "YF++ZF4-XF[-YF4-WF]++";
//    ruleX = "+YF--ZF[3-WF--XF]+";
//    ruleY = "-WF++XF[+++YF++ZF]-";
//    ruleZ = "--YF++++WF[+ZF++++XF]--XF";
//    startLength = 460.0;
//    theta = radians(36);  
//

#define maxLayer 4

#define TAU 6.28318531

// 
const int D[26 * 5] = int[](
        // [X]++[X]++[X]++[X]++[X]
  // [X] or X accelerate 
    -20+23, 7, 1, 8, 5, 5, 7, 1, 8, 5, 5, 7, 1, 8, 5, 5, 7, 1, 8, 5, 5, 7, 1, 8, 0, 0,
        // +YF--ZF[---WF--XF]+
        19, 5, 2, 9, 6, 6, 3, 9, 7, 6, 6, 6, 4, 9, 6, 6, 1, 9, 8, 5, 0, 0, 0, 0, 0, 0,
        // -WF++XF[+++YF++ZF]-
        19, 6, 4, 9, 5, 5, 1, 9, 7, 5, 5, 5, 2, 9, 5, 5, 3, 9, 8, 6, 0, 0, 0, 0, 0, 0,
        // --YF++++WF[+ZF++++XF]--XF
        25, 6, 6, 2, 9, 5, 5, 5, 5, 4, 9, 7, 5, 3, 9, 5, 5, 5, 5, 1, 9, 8, 6, 6, 1, 9,
        // YF++ZF----XF[-YF----WF]++
        25, 2, 9, 5, 5, 3, 9, 6, 6, 6, 6, 1, 9, 7, 6, 2, 9, 6, 6, 6, 6, 4, 9, 8, 5, 5);

float dline(vec2 a, vec2 b, vec2 p) {
        b -= a;
        p -= a;
        return length(p - b * clamp(dot(p, b) / dot(b, b), 0., 1.));
}

void mainImage(out vec4 O, vec2 U) {
        vec2 R = iResolution.xy,
                u = 8. * (R - U - U).yx / R.y;

        //---------------------------
        // Utilizing symmetry to decompose and accelerate
        float a = atan(u.y,u.x), r =length(u);
        a -= round(a/TAU*5.)/5.*TAU;// a = abs(a)-.5
        u = r * vec2(cos(a),sin(a));
        //u.y = abs(u.y);
        //---------------------------

        O = vec4(0);
        ivec2 func[9];
        vec3 p = vec3(0), mtr[9];
        int c, ptr = 0, lyr = 0;
        vec2 cs[10], csi;
        float d = 1e8,d2 = 1e8,dx;

        for (float i = 0.; i < 10.; i++) cs[int(i)] = vec2(cos(i / 10. * TAU), sin(i / 10. * TAU));

        lyr = 0;
        func[lyr] = ivec2(1, 0);
        for(float i;i<200000.;i++)//for (int i = 0; i < 200000; i++) // for(;;) 
        {
                //--------------------.
                // animation demonstration
                if(i>iTime*50.-100. && iTime>2.)
                {                    
                        O = vec4(.6,.3,0,0) ;
                        O.xy += smoothstep(30. / R.y, 0., d);                                                          
                        O.y -= smoothstep(60. / R.y, 0., d2);                                                          

                        return;                          
                }                    
                //--------------------

                c = D[func[lyr].y * 26 + func[lyr].x];
                func[lyr].x++;

                if (c > 0 && c < 5) { // four rules
                        if (lyr < maxLayer) {
                                lyr++;
                                func[lyr] = ivec2(1, c);
                        }
                } else if (c == 5) { // + rotate 36
                        p.z++;
                } else if (c == 6) { // - rotate -36
                        p.z--;
                } else if (c == 7) { // [ push
                        ptr++;
                        mtr[ptr] = p;
                } else if (c == 8) { // ] pop
                        p = mtr[ptr];
                        ptr--;
                } else if (c == 9) { // draw
                        if (lyr == maxLayer) {
                                d2=1e8;
                                csi = cs[(int(p.z)+100) % 10];
                                if (abs(u.x - p.x) < 1.1 && abs(u.y-p.y)<1.1){
                                          d = min(d, d2=dline(p.xy, p.xy + csi, u));
                                          //dx=dline(p.xy, p.xy + csi, u);
                                          //if(d>dx)d2=dx,d=dx;
                                }
                                p.xy += csi;
                        }
                }

                while (func[lyr].x > D[func[lyr].y * 26 + 0]) {
                        lyr--;
                        if (lyr < 0) {

                                O = .7 - vec4(smoothstep(40. / R.y, 0., d));

                                //O = vec4(.6,.3,0,0) ;
                                //O.xy += smoothstep(60. / R.y, 0., d);


                                return;
                        }
                }
        }
}
